CREATE OR REPLACE FUNCTION public.uuidv7() RETURNS uuid LANGUAGE sql VOLATILE AS $f$ SELECT encode(set_bit(set_bit(overlay(uuid_send(gen_random_uuid()) placing substring(int8send((extract(epoch FROM clock_timestamp()) * 1000)::bigint) FROM 3) FROM 1 FOR 6), 52, 1), 53, 1), 'hex')::uuid $f$;
CREATE OR REPLACE FUNCTION public.uuid_extract_version(u uuid) RETURNS smallint LANGUAGE sql IMMUTABLE AS $f$ SELECT (get_byte(uuid_send(u), 6) >> 4)::smallint $f$;
